export const meta = {
  name: 'wave2-callisto',
  description: 'Wave 2: status resolver fix, Python per-declaration locator, and false-absent provider reads; each in its own worktree then independently reviewed',
  phases: [
    { title: 'Implement', detail: 'one worktree per lane; tests first, scoped cargo only' },
    { title: 'Review', detail: 'independent adversarial review of each implementation' },
  ],
}

const BASE = '/Users/gabe/Projects/callisto/.claude/worktrees/wave2-base'

const RULES = `You are working on the Callisto repository (Rust workspace: callisto-model MIT, callisto-manifests, callisto-graph, callisto-cli). You were started in your own git worktree, created from the base tree ${BASE} (current main plus the open #223 change that adds DepLocator). Work only inside your worktree; never edit ${BASE} or any other path.

HARD CONSTRAINTS
- git commands are refused in this sandbox. Do NOT commit, branch, push or open PRs: leave your change uncommitted. Use ordinary file tools and cargo.
- Do NOT run \`just ci\`, \`just coverage\` or a whole-workspace test: the coordinator runs the full gate serially. Run only scoped checks for the crate(s) you touch: \`cargo test -p <crate> ...\`, \`cargo clippy -p <crate> --all-targets -- -D warnings\`, \`cargo fmt -p <crate>\`. One cargo command at a time.
- Repository rules (AGENTS.md): safe Rust only; TOML edits go through toml_edit and JSON edits preserve key order and indentation, never regex or line edits; file writes go through callisto_model::atomic::atomic_write; user-facing errors derive miette::Diagnostic with a code and a help line; no emojis; code comments are one short line and only for a non-obvious why, never history ("previously", "used to", "no longer"); never cite spec IDs, criterion IDs or section numbers in code, comments, test names or messages; no cargo features.
- Write the failing test FIRST, run it and confirm it fails for the right reason, then fix, then run again. Record the failing output in your report. Test adversarial inputs, not only the case being fixed.
- Time and focus: your runs have been dropped by the API after about 50 minutes. Work efficiently, avoid exploratory dead ends, and keep your final report ready; if you are past roughly 35 minutes of work, stop adding scope, make sure what you have compiles and its tests pass, and report.
- If you cannot reproduce the problem as described, STOP and report what you found instead of inventing a fix.
- Be precise in your report. Never claim a command passed unless you ran it and saw it pass; list what you could not run.`

const IMPL_SCHEMA = {
  type: 'object',
  properties: {
    worktree: { type: 'string', description: 'absolute path of your worktree' },
    stopped_early: { type: 'boolean' },
    stop_reason: { type: 'string' },
    summary: { type: 'string' },
    files_changed: { type: 'array', items: { type: 'string' } },
    tests_added: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          file: { type: 'string' },
          failed_before_fix: { type: 'boolean' },
          failure_evidence: { type: 'string' },
        },
        required: ['name', 'file', 'failed_before_fix'],
      },
    },
    commands_run: {
      type: 'array',
      items: {
        type: 'object',
        properties: { command: { type: 'string' }, result: { type: 'string' } },
        required: ['command', 'result'],
      },
    },
    not_run: { type: 'array', items: { type: 'string' } },
    design_notes: { type: 'string' },
    public_api_changes: { type: 'array', items: { type: 'string' } },
    changeset_text: { type: 'string', description: 'one or two sentences a user would read, no internal names' },
    risks: { type: 'array', items: { type: 'string' } },
  },
  required: ['worktree', 'stopped_early', 'summary', 'files_changed', 'tests_added', 'commands_run', 'not_run'],
}

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['approve', 'changes-needed', 'reject'] },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          where: { type: 'string' },
          scenario: { type: 'string', description: 'concrete inputs and state, then the wrong behavior' },
          confirmed_by: { type: 'string', enum: ['ran-a-test', 'read-the-code'] },
        },
        required: ['severity', 'where', 'scenario', 'confirmed_by'],
      },
    },
    tests_run: { type: 'array', items: { type: 'string' } },
    not_checked: { type: 'array', items: { type: 'string' } },
  },
  required: ['verdict', 'findings', 'tests_run', 'not_checked'],
}

const STATUS_PROMPT = `${RULES}

TASK (status resolves changeset selectors like version does).
Background, verified by a reproduction: \`callisto status\` resolves each changeset entry through PackageId::resolve_unique (crates/callisto-model/src/identity.rs; used in crates/callisto-graph/src/commands/status.rs around lines 28-60 and 170-210), which matches against the package's PRIMARY id and treats a qualified selector with an ecosystem the package lacks as a wildcard. \`callisto version\` resolves through the identity index (IdentityIndex::resolve_id, crates/callisto-graph/src/identity.rs, used via resolve_target_package in crates/callisto-graph/src/aggregate.rs around line 317). docs/specs/workspace.json defines no display-level matching: it requires a changeset entry naming a package by a non-primary manifest's own name to resolve, a qualified name with no such manifest to fail, and a bare name shared by promoted packages to be ambiguous. So status is the one violating the spec.

The tests already exist in crates/callisto-cli/tests/status_version_selector_tests.rs: eight pass today, and six are marked #[ignore = "status and version resolve this selector differently"] (secondary native name bare and qualified on a dual-manifest package; qualified selector for an ecosystem lacking the name; the other manifest's primary name; a bare name that is one package's primary and another's secondary; a qualified secondary name that status attaches to the wrong package).

Steps
1. Run the six ignored tests (\`cargo test -p callisto-cli --test status_version_selector_tests -- --ignored\`) and record the failures. These are your failing-first tests.
2. Make status resolve through the same resolver as version, in both places it resolves (changeset attribution and the well-formedness checks), so the six tests pass. Remove the #[ignore] from them. Keep the eight passing tests passing. Keep what the CLI spec mandates for an unknown name: \`status --check\` reports unknown-package and exits 1 (docs/specs/cli.json), while version only warns. Do not change version's behavior.
3. grep for every other caller of PackageId::resolve_unique across crates (including config group resolution, status_cascade_and_wellformedness tests, the fixtures crate). It is public API of the published callisto-model crate: if status was its only production caller, mark it #[deprecated(note = "...")] pointing at the identity index and keep it working (no removal); if there are other production callers, do not deprecate it and report them as siblings with the same defect or not.
4. Check the side effects found in the reproduction are gone: a package reported as both planned and unknown at once, and \`status --check\` exiting 0 for a changeset that version will never consume.
5. Adversarial tests beyond the six: a changeset naming two selectors that resolve to one package, a selector in a config group, a pre-release workspace.
Scoped verification only (callisto-model, callisto-graph, callisto-cli). Record public_api_changes (a deprecation is not a break) and suggest changeset text. Do not edit docs/projects/*; report whether docs/specs or docs/errors.md need a change.`

const PYTHON_PROMPT = `${RULES}

TASK (Python: every declaration of a requirement is its own edge, like Cargo).
Background: the open change in your base tree (crates/callisto-model/src/dependency.rs, DepLocator; crates/callisto-manifests/src/cargo.rs; crates/callisto-graph/tests/cargo_declaration_edges_test.rs; .changeset/noble-foxes-climb.md) made every Cargo dependency declaration its own edge, addressed by a DepLocator, and rewritten independently. Read that change first and follow its design. Python still has the original defect, confirmed by an independent reviewer: crates/callisto-manifests/src/python.rs iter_dependencies (around lines 459-557) emits one edge per declaration but they all carry DepLocator::default(), so they share one RewriteKey; the writer update_dependency_spec (around lines 560-700) rewrites only declarations carrying the FIRST declaration's constraint (see the extras block, comment "1b. Extras") and, for [project.dependencies], replaces the first match and breaks.
Scenarios that must work after the fix:
  A. extras:  [project.optional-dependencies] a = ["b>=1.0"]  c = ["b==1.0.0"]  and b is released at 1.1.0: the loose one stays valid or gets its floor handled as for any plain requirement, and the stale pin "b==1.0.0" is rewritten; neither declaration is rewritten using the other's constraint.
  B. markers: dependencies = ["b==1.0.0; python_version<'3.9'", "b==1.0.0; python_version>='3.9'"]: both lines are rewritten, markers preserved.
  C. the same requirement in [project.dependencies] and in an extra, and in Poetry tables ([tool.poetry.dependencies] and groups) and [dependency-groups] if the code already reads them (do not add new table support).
Design: extend the locator so Python can say which declaration: the container (project dependencies, an extra by name, a Poetry table) and the position within it. Keep Cargo and npm behavior unchanged. Position is only valid for one plan-then-apply run: validate at write time that the requirement found at that position still has the same normalized name, and fail with the existing DependencyNotFound error instead of rewriting a different declaration. Prefer adding fields to DepLocator with defaults over a new type; if you make the struct #[non_exhaustive] to stop future breaks, provide constructors and migrate every call site (the Cargo code constructs DepLocator with struct-literal syntax; update it). Record every public signature change.
Steps: (1) reproduce each scenario black-box with the real binary (see crates/callisto-cli/tests/python_dependency_tables_tests.rs and the existing extras tests added for Python extras; model a fixture on them) and at the unit level; show the stale or wrongly-rewritten result. (2) implement. (3) tests: A, B, C, requirement with extras syntax b[x]>=1, normalized-name spellings (Foo_Bar vs foo-bar), a stale locator, format and comment preservation of untouched lines, and Cargo/npm regression tests still passing. (4) scoped verification: callisto-model, callisto-manifests, callisto-graph, callisto-cli, one at a time. Also remove the changeset sentence that says Python requirements declared twice are still followed by their first declaration only: do that by reporting the exact sentence in .changeset/noble-foxes-climb.md that should change (the coordinator edits the changeset); do not edit .changeset files yourself. Suggest changeset text.`

const ABSENT_PROMPT = `${RULES}

TASK (provider observations must not read an error as "the remote object is absent").
Absent mints an absent proof, after which a publish or tag effect is attempted; so a failure to look must never be classified Absent. A read-only audit found these in crates/callisto-graph/src/commands/release/provider/:
  1. tag.rs observed_local_tag (around lines 248-257): \`git rev-parse --verify --quiet refs/tags/<name>^{commit}\` with ANY non-zero exit returns LocalTagObservation::Absent. git exits 1 for a missing ref under --verify --quiet; other failures (128 for a fatal error such as not a repository, a corrupt object database or a permission problem) are not absence. Only the missing-ref exit with empty stdout may be Absent; anything else must become a typed error (CommandFailure::NonZeroExit carrying stderr, as the sibling for-each-ref call in the same function already does).
  2. registry.rs npm observation (around lines 450-472): an npm view result is treated as Absent when the lowercased stdout+stderr merely CONTAINS e404, etarget or "no matching version", including for a non-zero exit, and for exit 0 with empty stdout. Examine the real captured outputs in testing/fixtures/providers/ (see PROVENANCE.md files there) and what \`npm view --json\` prints on error ({"error":{"code":"E404",...}}). Replace the substring match on free text by parsing the structured JSON error code when stdout is JSON, keeping the captured-fixture tests passing; decide what a non-JSON non-zero exit means (an Indeterminate command failure, not Absent) and say what you chose. Exit 0 with empty stdout needs a documented decision: report what npm really does.
Also check for the same defect class in the sibling providers (tag.rs remote ls-remote parsing, forge.rs, artifact.rs, release/github.rs) and the cargo adapter: report each place where a non-zero exit, empty output or a free-text match is turned into Absent, whether it is intended (for example a GitHub 404 for a release by tag is the documented answer) and whether you changed it. Do NOT change: cargo's yanked-version-is-absent rule, the PyPI classifier (file-set completion is a separate decision), or any Timeout/Unauthorized cause wiring.
Tests first: a fake CommandRunner returning exit 128 for the local rev-parse must yield an error not Absent (the provider tests already have runner fakes; see tag.rs tests and registry/tests.rs), exit 1 with empty stdout stays Absent, and for npm each of: JSON E404 -> Absent, JSON E401/E403/other code -> not Absent, non-JSON failure -> not Absent, plus the real captured fixtures. Also add one end-to-end check through the real executor path if one exists cheaply (an executor run whose observation errors must not attempt the effect).
Scoped verification: callisto-graph (and callisto-model if touched) only. Suggest changeset text if a user would see a difference (for example a corrupted repository now fails the release with a clear error instead of attempting to publish).`

const LANES = [
  { key: 'status', prompt: STATUS_PROMPT },
  { key: 'python', prompt: PYTHON_PROMPT },
  { key: 'absent', prompt: ABSENT_PROMPT },
]

const results = await pipeline(
  LANES,
  (lane) => agent(lane.prompt, { label: `implement:${lane.key}`, phase: 'Implement', schema: IMPL_SCHEMA, isolation: 'worktree' }),
  (impl, lane) => {
    if (!impl) return null
    if (impl.stopped_early) return { key: lane.key, impl, review: null }
    return agent(
      `You are an independent, adversarial reviewer. Another engineer implemented this task in the worktree ${impl.worktree}. The unmodified base tree is ${BASE}. Do NOT edit anything in either tree and do NOT run git (it is refused). Compare the two with \`diff -ru\` on the relevant crate src and tests directories (exclude target/), and read the changed files in full.

TASK THEY WERE GIVEN:
${lane.prompt}

