p = '/Users/gabe/Projects/callisto/.claude/worktrees/docs-prune-2/docs/projects/V1-SYSTEM-HARDENING.json'
d = json.load(open(p))
shipped = {'T08-RETRY', 'T10'}
d['tasks'] = [t for t in d['tasks'] if t['id'] not in shipped]
for t in d['tasks']:
    if 'depends_on' in t:
        t['depends_on'] = [x for x in t['depends_on'] if x not in shipped]
        if not t['depends_on']:
            del t['depends_on']
    if t['id'] == 'T08':
        t['steps'][0] = (
