            'distribution, and package dependencies order all owner outputs.'
        )
kept = []
for b in d['batches']:
    b['task_ids'] = [x for x in b['task_ids'] if x not in shipped]
    if b['task_ids']:
        kept.append(b)
d['batches'] = kept
open(p, 'w').write(json.dumps(d, indent=2, ensure_ascii=False) + "\n")
print([t['id'] for t in d['tasks']])
print([(b['batch_id'], b['task_ids']) for b in d['batches']])
import re
