fn a_position_counts_entries_the_graph_does_not_read() {
    let dir = tempdir().unwrap();
    let manifest = open_pyproject(
        dir.path(),
        "[project]\nname = \"app\"\nversion = \"0.1.0\"\ndependencies = [\"\", \"a>=1\", \">=2\", \"b==1\"]\n",
    );
    let positions: Vec<_> = manifest
        .iter_dependencies()
