17	impl Rosters {
18	    fn declaring_at(&mut self, git: &GitAccess<'_>, rev: &str, name: &str) -> Result<BTreeSet<Ecosystem>, GraphError> {
19	        let key = (rev.to_string(), name.to_string());
20	        if let Some(known) = self.0.get(&key) {
