40	/// Whether `rev` held a manifest of `ecosystem` declaring `name`; only manifests mentioning it are read.
41	fn declares(
42	    git: &GitAccess<'_>,
43	    rev: &str,
44	    name: &str,
45	    ecosystem: Ecosystem,
46	    format: ManifestFormat,
47	    file_name: &str,
48	) -> Result<bool, GraphError> {
49	    // A normalized Python name may be spelled with other separators, so search its first word.
50	    let needle = match ecosystem {
51	        Ecosystem::Pypi => name
52	            .split(['-', '_', '.'])
53	            .find(|word| !word.is_empty())
54	            .unwrap_or(name),
55	        _ => name,
56	    };
57	    for path in git.files_containing_at(rev, needle, &[&format!(":(glob)**/{file_name}")])? {
58	        let Some(text) = git.read_at(rev, &path)? else {
59	            continue;
60	        };
61	        // A manifest that was broken at `rev` simply names nobody.
62	        let declared = read_identity(format, &text, &path)
63	            .ok()
64	            .and_then(|identity| identity.name);
65	        if declared.is_some_and(|declared| names_equal(ecosystem, &declared, name)) {
66	            return Ok(true);
67	        }
68	    }
69	    Ok(false)
70	}
