72	fn names_equal(ecosystem: Ecosystem, left: &str, right: &str) -> bool {
73	    match ecosystem {
74	        Ecosystem::Pypi => normalize_pypi_project_name(left) == normalize_pypi_project_name(right),
75	        _ => left == right,
76	    }
