    adapter_for(Ecosystem::Npm).unwrap().publish(&context, &owner).unwrap();
    assert_eq!(runner.0.lock().unwrap()[0].0, "pnpm");
    assert!(runner.0.lock().unwrap()[0].1.contains(&"--filter=@s/cli".to_owned()));
}

