        probe_atomic_write(&target, &permit).unwrap();
        assert_eq!(std::fs::read_dir(target.parent().unwrap()).unwrap().count(), 0);
        std::fs::write(&target, "x").unwrap();
        probe_atomic_write(&target, &permit).unwrap();
        assert!(probe_atomic_write(dir.path(), &permit).is_err());
    }

