fn read_root_manifest(path: &Path) -> Result<Option<String>, LocateError> {
    match callisto_model::strict_fs::read_optional(path) {
        Ok(content) => Ok(content.map(|text| text.strip_prefix('\\u{FEFF}').map_or(text.clone(), str::to_owned))),
