    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    write(root, "native/Cargo.toml", "[workspace]\nmembers = [\"crates/*\"]\n[workspace.package]\nversion = \"1.0.0\"\n");
    write(
        root,
        "native/crates/a/Cargo.toml",
        "[package]\nname = \"a\"\nversion.workspace = true\n",
    );

    let locator = IgnoreWalkLocator::new(root);
    let error = Workspace::load(root.to_path_buf(), &locator, &NoopRunner).err().unwrap();
    let unresolved = unresolved_of(error);
    assert_eq!(unresolved.len(), 1, "one entry per manifest: {unresolved:?}");
