109	/// E101 when a package's default template (`{name}@{version}`) is also another package's template.
110	fn reject_shared_default_templates<D: DependencyResolver>(graph: &D) -> Result<(), GraphError> {
111	    let mut by_template: BTreeMap<String, (bool, Vec<PackageId>)> = BTreeMap::new();
112	    for pkg in graph.packages() {
113	        let tmpl = pkg
114	            .tag_template
115	            .clone()
116	            .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
117	        let (has_default, ids) = by_template.entry(tmpl.as_str()).or_default();
118	        *has_default |= pkg.tag_template.is_none();
119	        ids.push(pkg.id.clone());
120	    }
121	    match by_template
122	        .into_iter()
123	        .find(|(_, (has_default, ids))| *has_default && ids.len() > 1)
124	    {
125	        Some((template, (_, packages))) => Err(GraphError::SharedDefaultTagTemplate { template, packages }),
126	        None => Ok(()),
127	    }
