    #[test]
    fn a_single_package_at_the_toplevel_is_the_root_from_a_subdirectory() {
        for (manifest, content) in [
            ("Cargo.toml", CRATE),
            ("package.json", r#"{"name":"app","version":"1.0.0"}"#),
            ("pyproject.toml", "[project]\nname = \"app\"\nversion = \"1.0.0\"\n"),
