        write(&root, "node_modules/lib/package.json", r#"{"name":"lib"}"#);
        assert_eq!(find(&root.join("vendor/some-dep")).unwrap(), root);
        assert_eq!(find(&root.join("node_modules/lib")).unwrap(), root);
    }

