pub fn cargo_workspace_of(workspace_root: &Path, manifest: &Path) -> Result<PathBuf, ManifestError> {
    let doc = load_document(workspace_root, manifest)?.ok_or_else(|| ManifestError::Read {
        path: manifest.to_path_buf(),
