fn a_check_ignore_failure_is_an_error_not_an_empty_answer() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("Cargo.toml"), "[package]\\nname = \\"r\\"\\nversion = \\"1.0.0\\"\\n").unwrap();
