/* oxlint-disable jsx-a11y/prefer-tag-over-role -- An inline SVG drawing is one named image; an img element cannot hold its shapes, so the svg takes the img role. */
import { diagram } from '@pages/twx/recipes'

// How Maestro answers: two sources feed the scoring, and only what fits comes back. It draws the post's own account of
// Maestro, with no figures. Wide runs left to right; the phone's drawing stacks the same three steps.
const ariaLabel =
  'How Maestro answers. Two sources, Storybook data and component guidance, feed the scoring. The scoring ranks likely matches, surfaces related parts and shows how they compose. The agent gets ranked components, how they relate and how to compose them.'

const sources = [
  { name: 'Storybook data', note: 'data, not the server' },
  { name: 'Component guidance', note: 'from data and source' },
] as const
const scoring = ['rank likely matches', 'surface related parts', 'show how they compose'] as const
const answers = ['Ranked components', 'How they relate', 'How to compose them'] as const

const diamond = (cx: number, cy: number, r: number) => `${cx},${cy - r} ${cx + r},${cy} ${cx},${cy + r} ${cx - r},${cy}`
const across = (x1: number, y: number, x2: number) => `M${x1} ${y}H${x2}M${x2 - 6} ${y - 5}l6 5-6 5`
const down = (x: number, y1: number, y2: number) => `M${x} ${y1}V${y2}M${x - 5} ${y2 - 6}l5 6 5-6`

export function MaestroPipeline() {
  const slots = diagram()
  return (
    <svg viewBox="0 0 760 232" role="img" aria-label={ariaLabel} className={slots.root}>
      <text className={slots.label} x="0" y="14">
        SOURCES
      </text>
      <text className={slots.label} x="270" y="14">
        MAESTRO SCORES
      </text>
      <text className={slots.label} x="550" y="14">
        THE AGENT GETS
      </text>
      {sources.map((source, i) => (
        <g key={source.name}>
          <rect className={slots.tile} x="0.75" y={30.75 + i * 92} width="198.5" height="76" rx="3" strokeWidth="1.5" />
          <text className={slots.text} x="16" y={62 + i * 92}>
            {source.name}
          </text>
          <text className={slots.label} x="16" y={86 + i * 92}>
            {source.note}
          </text>
          <path className={slots.inkLine} d={across(204, 68 + i * 92, 262)} strokeWidth="1.5" />
        </g>
      ))}
      <rect className={slots.tile} x="270.75" y="30.75" width="218.5" height="168" rx="3" strokeWidth="1.5" />
      <rect className={slots.ink} x="270.75" y="30.75" width="6" height="168" rx="3" />
      {scoring.map((line, i) => (
        <g key={line}>
          <polygon className={slots.gate} points={diamond(300, 72 + i * 42, 7)} strokeWidth="1.5" />
          <text className={slots.text} x="318" y={77 + i * 42}>
            {line}
          </text>
        </g>
      ))}
      <path className={slots.inkLine} d={across(494, 114, 542)} strokeWidth="1.5" />
      {answers.map((line, i) => (
        <g key={line}>
          <rect
            className={slots.tile}
            x="550.75"
            y={30.75 + i * 58}
            width="208.5"
            height="50"
            rx="3"
            strokeWidth="1.5"
          />
          <rect
            className={slots.ink}
            x="550.75"
            y={30.75 + i * 58}
            width="6"
            height="50"
            rx="3"
            opacity={1 - i * 0.3}
          />
          <text className={slots.text} x="572" y={61 + i * 58}>
            {line}
          </text>
        </g>
      ))}
    </svg>
  )
}

export function MaestroPipelineNarrow() {
  const slots = diagram()
  return (
    <svg viewBox="0 0 400 478" role="img" aria-label={ariaLabel} className={slots.root}>
      <text className={slots.label} x="0" y="14">
        SOURCES
      </text>
      {sources.map((source, i) => (
        <g key={source.name}>
          <rect
            className={slots.tile}
            x={0.75 + i * 208}
            y="30.75"
            width="190.5"
            height="68"
            rx="3"
            strokeWidth="1.5"
          />
          <text className={slots.text} x={14 + i * 208} y="60">
            {source.name}
          </text>
          <text className={slots.label} x={14 + i * 208} y="82">
            {source.note}
          </text>
          <path className={slots.inkLine} d={`M${96 + i * 208} 100V118`} strokeWidth="1.5" />
        </g>
      ))}
      <path className={slots.inkLine} d="M96 118H304" strokeWidth="1.5" />
      <path className={slots.inkLine} d={down(200, 118, 146)} strokeWidth="1.5" />
      <rect className={slots.tile} x="0.75" y="146.75" width="398.5" height="152" rx="3" strokeWidth="1.5" />
      <rect className={slots.ink} x="0.75" y="146.75" width="6" height="152" rx="3" />
      <text className={slots.label} x="22" y="170">
        MAESTRO SCORES
      </text>
      {scoring.map((line, i) => (
        <g key={line}>
          <polygon className={slots.gate} points={diamond(30, 200 + i * 34, 7)} strokeWidth="1.5" />
          <text className={slots.text} x="48" y={205 + i * 34}>
            {line}
          </text>
        </g>
      ))}
      <path className={slots.inkLine} d={down(200, 300, 328)} strokeWidth="1.5" />
      <text className={slots.label} x="0" y="346">
        THE AGENT GETS
      </text>
      {answers.map((line, i) => (
        <g key={line}>
          <rect
            className={slots.tile}
            x="0.75"
            y={358.75 + i * 40}
            width="398.5"
            height="34"
            rx="3"
            strokeWidth="1.5"
          />
          <rect className={slots.ink} x="0.75" y={358.75 + i * 40} width="6" height="34" rx="3" opacity={1 - i * 0.3} />
          <text className={slots.text} x="22" y={381 + i * 40}>
            {line}
          </text>
        </g>
      ))}
    </svg>
  )
}

