fn add_artifact_uploads<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
    owners: &Owners,
